<?php require '../includes/auth.php';require '../includes/header.php';$u=guard('admin',['payroll_manager']);csrf_check();
$m=(int)($_REQUEST['m']??date('n'));$y=(int)($_REQUEST['y']??date('Y'));$a=$_POST['_action']??'';$d=db();
if($a==='run'){$days=(int)date('t',mktime(0,0,0,$m,1,$y));$st=isset($_POST['auto'])?'Published':'Draft';$n=0;
 $emps=$d->query("SELECT e.*,s.basic,s.hra,s.special,s.other_allow,s.bonus,s.pf,s.esi,s.pt,s.tds,s.other_ded FROM employees e JOIN employee_salaries s ON s.employee_id=e.id WHERE e.status<>'Inactive'")->fetchAll();
 foreach($emps as $e){$x=$d->prepare("SELECT 1 FROM payslips WHERE employee_id=? AND month=? AND year=? AND revision=0");$x->execute([$e['id'],$m,$y]);if($x->fetch())continue;
  $q=$d->prepare("SELECT att_date,status FROM attendance_records WHERE employee_id=? AND EXTRACT(MONTH FROM att_date)=? AND EXTRACT(YEAR FROM att_date)=?");$q->execute([$e['id'],$m,$y]);$map=$q->fetchAll(PDO::FETCH_KEY_PAIR);$paid=0;
  for($i=1;$i<=$days;$i++){$ds=sprintf('%04d-%02d-%02d',$y,$m,$i);$s=$map[$ds]??(date('w',strtotime($ds))==0?'Weekly Off':'Absent');$paid+=['Present'=>1,'Half Day'=>.5,'Paid Leave'=>1,'Weekly Off'=>1,'Holiday'=>1][$s]??0;}
  $lop=$days-$paid;$E=['Basic Salary'=>$e['basic'],'HRA'=>$e['hra'],'Special Allowance'=>$e['special'],'Other Allowances'=>$e['other_allow'],'Performance Bonus'=>$e['bonus']];$gross=array_sum($E);
  $D=['Provident Fund'=>$e['pf'],'ESI'=>$e['esi'],'Professional Tax'=>$e['pt'],'TDS'=>$e['tds'],'Other Deductions'=>$e['other_ded'],'Loss of Pay'=>round($gross/$days*$lop,2)];$td=array_sum($D);
  $info=['code'=>$e['employee_code'],'name'=>$e['full_name'],'joining'=>$e['joining_date'],'bank'=>$e['bank_name'],'account'=>$e['account_no'],'ifsc'=>$e['ifsc'],'pan'=>$e['pan']];
  $d->prepare("INSERT INTO payslips(employee_id,month,year,earnings,deductions,emp_info,days,paid_days,lop_days,gross,total_ded,net,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)")->execute([$e['id'],$m,$y,json_encode($E),json_encode($D),json_encode($info),$days,$paid,$lop,$gross,$td,$gross-$td,$st]);$n++;}
 audit($u['id'],"Ran payroll $m/$y ($n slips, $st)");flash("$n payslip(s) generated as $st");redirect("payroll.php?m=$m&y=$y");}
if($a==='publish'&&!empty($_POST['ids'])){$ids=array_map('intval',$_POST['ids']);$d->prepare("UPDATE payslips SET status='Published' WHERE status='Draft' AND id IN(".implode(',',array_fill(0,count($ids),'?')).")")->execute($ids);audit($u['id'],'Published payslips '.implode(',',$ids));flash('Published');redirect("payroll.php?m=$m&y=$y");}
if($a==='adjust'){$adj=(float)$_POST['adj'];$d->prepare("UPDATE payslips SET adj_amount=?,remarks=?,net=gross-total_ded+? WHERE id=? AND status='Draft'")->execute([$adj,trim($_POST['remarks']),$adj,(int)$_POST['id']]);audit($u['id'],'Adjusted payslip #'.(int)$_POST['id']);redirect("payroll.php?m=$m&y=$y");}
if($a==='revise'&&trim($_POST['reason'])!==''){$d->prepare("INSERT INTO payslips(employee_id,month,year,earnings,deductions,emp_info,days,paid_days,lop_days,gross,total_ded,net,adj_amount,remarks,revision,revision_reason) SELECT employee_id,month,year,earnings,deductions,emp_info,days,paid_days,lop_days,gross,total_ded,net,adj_amount,remarks,(SELECT MAX(revision)+1 FROM payslips p2 WHERE p2.employee_id=p.employee_id AND p2.month=p.month AND p2.year=p.year),? FROM payslips p WHERE id=? AND status='Published'")->execute([trim($_POST['reason']),(int)$_POST['id']]);audit($u['id'],'Revision created from payslip #'.(int)$_POST['id']);flash('Revision created as Draft');redirect("payroll.php?m=$m&y=$y");}
$r=$d->prepare("SELECT p.*,e.employee_code,e.full_name FROM payslips p JOIN employees e ON e.id=p.employee_id WHERE month=? AND year=? ORDER BY e.employee_code,p.revision");$r->execute([$m,$y]);page_head('Payroll',[],$u);?>
<form method="post" class="card p-3 mb-3 d-flex flex-row flex-wrap gap-2 align-items-center"><?=csrf_field()?><input type="hidden" name="_action" value="run"><select class="form-select w-auto" name="m"><?php for($i=1;$i<=12;$i++)echo'<option value="'.$i.'"'.($i==$m?' selected':'').'>'.date('F',mktime(0,0,0,$i,1)).'</option>';?></select><input class="form-control w-auto" type="number" name="y" value="<?=$y?>"><label class="form-check"><input type="checkbox" class="form-check-input" name="auto"> Auto-publish</label><button class="btn btn-primary">Run payroll calculation</button><span class="small text-muted">Unmarked non-Sunday days count as LOP — review attendance first.</span></form>
<form id="bulk" method="post"><?=csrf_field()?><input type="hidden" name="_action" value="publish"><input type="hidden" name="m" value="<?=$m?>"><input type="hidden" name="y" value="<?=$y?>"></form>
<div class="card table-responsive"><table class="table mb-0 align-middle"><tr><th><button form="bulk" class="btn btn-sm btn-success">Publish selected</button></th><th>Employee</th><th>Paid/LOP</th><th>Gross</th><th>Net</th><th>Status</th><th>Actions</th></tr>
<?php foreach($r as $p){?><tr><td><?php if($p['status']==='Draft')echo'<input type="checkbox" form="bulk" name="ids[]" value="'.$p['id'].'">';?></td><td><?=e($p['employee_code'].' '.$p['full_name'])?></td><td><?=e($p['paid_days'])?>/<?=e($p['lop_days'])?></td><td><?=money($p['gross'])?></td><td><?=money($p['net'])?></td><td><span class="badge text-bg-<?=$p['status']==='Published'?'success':'secondary'?>"><?=e($p['status'])?></span><?=$p['revision']?' <span class="badge text-bg-warning">Rev '.$p['revision'].'</span>':''?></td>
<td><a class="btn btn-sm btn-outline-primary" href="payslip.php?id=<?=$p['id']?>">View</a>
<?php if($p['status']==='Draft'){?><form method="post" class="d-inline-flex gap-1"><?=csrf_field()?><input type="hidden" name="_action" value="adjust"><input type="hidden" name="id" value="<?=$p['id']?>"><input type="hidden" name="m" value="<?=$m?>"><input type="hidden" name="y" value="<?=$y?>"><input class="form-control form-control-sm" style="width:90px" type="number" step="0.01" name="adj" value="<?=e($p['adj_amount'])?>" title="+bonus / -deduction"><input class="form-control form-control-sm" name="remarks" placeholder="Remarks" value="<?=e($p['remarks'])?>"><button class="btn btn-sm btn-outline-secondary">Adjust</button></form>
<?php }else{?><form method="post" class="d-inline-flex gap-1"><?=csrf_field()?><input type="hidden" name="_action" value="revise"><input type="hidden" name="id" value="<?=$p['id']?>"><input type="hidden" name="m" value="<?=$m?>"><input type="hidden" name="y" value="<?=$y?>"><input class="form-control form-control-sm" name="reason" placeholder="Reason (required)" required><button class="btn btn-sm btn-outline-warning">Revise</button></form><?php }?></td></tr><?php }?></table></div><?php page_foot();
